export default function Preview() {
  const [step, setStep] = useState(0)
  const totalSteps = 5

  useEffect(() => {
    const interval = setInterval(
      () => {
        setStep((prev) => {
          if (prev === totalSteps - 1) {
            // Wait longer on the last step
            return 0
          }
          return prev + 1
        })
      },
      step === totalSteps - 1 ? 5000 : 3000
    ) // 4 seconds for last step, 2 seconds for others

    return () => clearInterval(interval)
  }, [step])

  const getSecondFaceTransform = () => {
    switch (step) {
      case 0:
        return `rotateX(0deg)`
      case 1:
        return `rotateX(0deg)`
      case 2:
        return "rotateX(90deg)"
      case 3:
        return "rotateX(90deg) translateZ(0.5lh)"
      case 4:
        return "rotateX(90deg) translateZ(0.5lh)"
      default:
        return "rotateX(0deg)"
    }
  }

  const getFirstFaceTransform = () => {
    switch (step) {
      case 0:
        return "translateZ(0lh)"
      case 1:
        return "translateZ(0.5lh)"
      case 2:
        return "translateZ(0.5lh)"
      case 3:
        return "translateZ(0.5lh)"
      case 4:
        return "translateZ(0.5lh)"
      default:
        return "translateZ(0lh)"
    }
  }

  const getContainerTransform = () => {
    switch (step) {
      case 0:
        return "translateZ(0)"
      case 1:
        return "translateZ(0)"
      case 2:
        return "translateZ(0)"
      case 3:
        return "translateZ(0)"
      case 4:
        return "translateZ(-0.5lh)"
      default:
        return "translateZ(0)"
    }
  }

  const getDisplayTransform = () => {
    switch (step) {
      case 0:
        return [" ", " "]
      case 1:
        return ["1st face:", "translateZ(0.5lh)"]
      case 2:
